ostream_iterator<int> out_it(cout, ", ");

// Operation 1: Assignment (Write)
// Assignment *must* be followed by advancement
*out_it = 42;
out_it++;
*out_it = 99;

// Operation 2: Used as sink in algorithms
vector<int> src = {1, 2, 3};
copy(src.begin(), src.end(), out_it);

// Example of helper returning an Output Iterator
list<int> L;
auto insert_it = back_inserter(L);
*insert_it = 100;
insert_it++;
*insert_it = 200;

